
local csp=[==[]==]
local cgln=
(function(...)
local youej={111,141,124,216,215,69,184,46,139,123,202,123,173,250,42,65,240,178,122,98,210,227,240,185,178,4,238,255}
local jk=bit32 or bit
local cugy=jk.bxor
for xtsjp=1,#youej do youej[xtsjp]=cugy(youej[xtsjp],(117*xtsjp+61)%256) end
local istc="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local rj={}
for lh=1,#istc do rj[istc:byte(lh)]=lh-1 end
local function azou(str)
  local R={} local acc,nb=0,0
  for olcu=1,#str do
    local v=rj[str:byte(olcu)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function oovuq(key,data)
  local S={} for vezsp=0,255 do S[vezsp]=vezsp end
  local j=0
  for zxpxa=0,255 do
    j=(j+S[zxpxa]+key[(zxpxa%#key)+1])%256
    S[zxpxa],S[j]=S[j],S[zxpxa]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(cugy(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=oovuq(youej,azou(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local axnv=nf()
return function(big) return axnv(big) end
end)(...)

return cgln(csp)
